1	// Meeting-room booking server: JSON API, browser page, one JSON data file.
2	// Node.js built-ins only.
3	import http from 'node:http';
4	import fs from 'node:fs';
5	import path from 'node:path';
6	import { fileURLToPath } from 'node:url';
7	
8	const HOST = '127.0.0.1';
9	const DEFAULT_PORT = 3000;
10	const MAX_PORT = 65535;
11	const MAX_BODY_BYTES = 10000;
12	const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
13	const BOOKING_KEYS = Object.freeze(['id', 'room', 'title', 'date', 'start', 'end']);
14	const JSON_TYPE = 'application/json; charset=utf-8';
15	const PUBLIC_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), 'public');
16	const PAGES = Object.freeze({
17	  '/': { file: 'index.html', type: 'text/html; charset=utf-8' },
18	  '/app.js': { file: 'app.js', type: 'text/javascript; charset=utf-8' },
19	});
20	const DELETE_ROUTE = /^\/api\/bookings\/[^/]+$/;
21	const ID_PATTERN = /^[1-9][0-9]*$/;
22	const DATE_PATTERN = /^([0-9]{4})-([0-9]{2})-([0-9]{2})$/;
23	const TIME_PATTERN = /^([0-9]{2}):([0-9]{2})$/;
24	
25	const MSG = Object.freeze({
26	  contentType: 'content type must be application/json',
27	  tooLarge: 'body too large',
28	  notObject: 'body must be a JSON object',
29	  room: 'room must be one of Aurora, Borealis, Cosmos',
30	  title: 'title must be 1 to 80 characters',
31	  date: 'date must be a valid YYYY-MM-DD date',
32	  start: 'start must be HH:MM',
33	  end: 'end must be HH:MM',
34	  order: 'end must be after start',
35	  bookingNotFound: 'booking not found',
36	  notFound: 'not found',
37	  method: 'method not allowed',
38	  internal: 'internal error',
39	});
40	
41	/** Thrown for a request that must get a specific error reply. */
42	class HttpError extends Error {
43	  constructor(status, message) {
44	    super(message);
45	    this.status = status;
46	  }
47	}
48	
49	// ---------- field validation (shared by the API and the data-file check) ----------
50	
51	const isPlainObject = (value) =>
52	  typeof value === 'object' && value !== null && !Array.isArray(value);
53	
54	function isValidDate(value) {
55	  if (typeof value !== 'string') return false;
56	  const match = DATE_PATTERN.exec(value);
57	  if (!match) return false;
58	  const [year, month, day] = match.slice(1).map(Number);
59	  if (year < 2000 || year > 2099 || month < 1 || month > 12 || day < 1) return false;
60	  const febDays = year % 4 === 0 ? 29 : 28;
61	  const monthDays = [31, febDays, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
62	  return day <= monthDays[month - 1];
63	}
64	
65	function isValidTime(value) {
66	  if (typeof value !== 'string') return false;
67	  const match = TIME_PATTERN.exec(value);
68	  return match !== null && Number(match[1]) <= 23 && Number(match[2]) <= 59;
69	}
70	
71	const isValidTitle = (value) =>
72	  typeof value === 'string' && value.trim().length >= 1 && value.trim().length <= 80;
73	
74	const overlaps = (a, b) =>
75	  a.room === b.room && a.date === b.date && a.start < b.end && b.start < a.end;
76	
77	/** Rules 4-9 on a parsed body; returns the new booking fields or throws HttpError. */
78	function validateFields(body) {
79	  if (typeof body.room !== 'string' || !ROOMS.includes(body.room)) throw new HttpError(400, MSG.room);
80	  if (!isValidTitle(body.title)) throw new HttpError(400, MSG.title);
81	  if (!isValidDate(body.date)) throw new HttpError(400, MSG.date);
82	  if (!isValidTime(body.start)) throw new HttpError(400, MSG.start);
83	  if (!isValidTime(body.end)) throw new HttpError(400, MSG.end);
84	  if (!(body.end > body.start)) throw new HttpError(400, MSG.order);
85	  return { room: body.room, title: body.title.trim(), date: body.date, start: body.start, end: body.end };
86	}
87	
88	// ---------- data file ----------
89	
90	const emptyState = () => Object.freeze({ nextId: 1, bookings: Object.freeze([]) });
91	
92	function isStoredBooking(b) {
93	  if (!isPlainObject(b)) return false;
94	  const keys = Object.keys(b);
95	  if (keys.length !== BOOKING_KEYS.length || !BOOKING_KEYS.every((k) => keys.includes(k))) return false;
96	  return Number.isSafeInteger(b.id) && b.id >= 1 && ROOMS.includes(b.room)
97	    && isValidTitle(b.title) && b.title === b.title.trim()
98	    && isValidDate(b.date) && isValidTime(b.start) && isValidTime(b.end) && b.end > b.start;
99	}
100	
101	/** Strict check that `data` is exactly the layout this server writes. */
102	function isValidLayout(data) {
103	  if (!isPlainObject(data)) return false;
104	  const keys = Object.keys(data);
105	  if (keys.length !== 2 || !keys.includes('nextId') || !keys.includes('bookings')) return false;
106	  const { nextId, bookings } = data;
107	  if (!Number.isSafeInteger(nextId) || nextId < 1 || !Array.isArray(bookings)) return false;
108	  if (!bookings.every(isStoredBooking)) return false;
109	  const ids = new Set(bookings.map((b) => b.id));
110	  if (ids.size !== bookings.length || bookings.some((b) => b.id >= nextId)) return false;
111	  return !bookings.some((b, i) => bookings.slice(i + 1).some((other) => overlaps(b, other)));
112	}
113	
114	/** Reads the data file once; returns the state or null when it cannot be used. */
115	function loadState(filePath) {
116	  let text;
117	  try {
118	    text = fs.readFileSync(filePath, 'utf8');
119	  } catch (err) {
120	    return err.code === 'ENOENT' ? emptyState() : null;
121	  }
122	  let data;
123	  try {
124	    data = JSON.parse(text);
125	  } catch {
126	    return null;
127	  }
128	  if (!isValidLayout(data)) return null;
129	  return Object.freeze({ nextId: data.nextId, bookings: Object.freeze(data.bookings.map((b) => Object.freeze({ ...b }))) });
130	}
131	
132	const saveState = (filePath, state) =>
133	  fs.promises.writeFile(filePath, JSON.stringify({ nextId: state.nextId, bookings: state.bookings }));
134	
135	// ---------- request plumbing ----------
136	
137	/** Reads the whole body; keeps at most MAX_BODY_BYTES + 1 bytes but counts every byte received. */
138	function readBody(req) {
139	  return new Promise((resolve, reject) => {
140	    const chunks = [];
141	    let kept = 0;
142	    let total = 0;
143	    req.on('data', (chunk) => {
144	      total += chunk.length;
145	      if (kept <= MAX_BODY_BYTES) {
146	        chunks.push(chunk);
147	        kept += chunk.length;
148	      }
149	    });
150	    req.on('end', () => resolve({ buffer: Buffer.concat(chunks), size: total }));
151	    req.on('error', reject);
152	    req.on('aborted', () => reject(new Error('request aborted')));
153	  });
154	}
155	
156	function send(res, status, payload) {
157	  if (status === 204) {
158	    res.writeHead(204);
159	    res.end();
160	    return;
161	  }
162	  const body = JSON.stringify(payload);
163	  res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': Buffer.byteLength(body) });
164	  res.end(body);
165	}
166	
167	const sendError = (res, status, message) => send(res, status, { error: message });
168	
169	function isJsonContentType(header) {
170	  if (typeof header !== 'string') return false;
171	  const media = header.split(';')[0].replace(/^[ \t]+|[ \t]+$/g, '');
172	  return media.toLowerCase() === 'application/json';
173	}
174	
175	function parseObjectBody(buffer) {
176	  let parsed;
177	  try {
178	    parsed = JSON.parse(buffer.toString('utf8'));
179	  } catch {
180	    throw new HttpError(400, MSG.notObject);
181	  }
182	  if (!isPlainObject(parsed)) throw new HttpError(400, MSG.notObject);
183	  return parsed;
184	}
185	
186	function compareBookings(a, b) {
187	  if (a.date !== b.date) return a.date < b.date ? -1 : 1;
188	  if (a.start !== b.start) return a.start < b.start ? -1 : 1;
189	  return ROOMS.indexOf(a.room) - ROOMS.indexOf(b.room);
190	}
191	
192	// ---------- application ----------
193	
194	function createApp(dataFile, initialState) {
195	  let state = initialState;
196	
197	  function listBookings(query) {
198	    const params = new URLSearchParams(query);
199	    let bookings = state.bookings;
200	    if (params.has('date')) {
201	      const date = params.get('date');
202	      if (!isValidDate(date)) throw new HttpError(400, MSG.date);
203	      bookings = bookings.filter((b) => b.date === date);
204	    }
205	    return { status: 200, payload: { bookings: [...bookings].sort(compareBookings) } };
206	  }
207	
208	  async function createBooking(req, body) {
209	    if (!isJsonContentType(req.headers['content-type'])) throw new HttpError(415, MSG.contentType);
210	    if (body.size > MAX_BODY_BYTES) throw new HttpError(413, MSG.tooLarge);
211	    const fields = validateFields(parseObjectBody(body.buffer));
212	    const clashes = state.bookings.filter((b) => overlaps(b, fields));
213	    if (clashes.length > 0) {
214	      const first = clashes.reduce((a, b) => (b.start < a.start ? b : a));
215	      throw new HttpError(409, `room is already booked from ${first.start} to ${first.end}`);
216	    }
217	    const booking = Object.freeze({ id: state.nextId, ...fields });
218	    await commit({ nextId: state.nextId + 1, bookings: [...state.bookings, booking] });
219	    return { status: 201, payload: booking };
220	  }
221	
222	  async function deleteBooking(rawId) {
223	    const id = ID_PATTERN.test(rawId) ? Number(rawId) : NaN;
224	    if (!state.bookings.some((b) => b.id === id)) throw new HttpError(404, MSG.bookingNotFound);
225	    await commit({ nextId: state.nextId, bookings: state.bookings.filter((b) => b.id !== id) });
226	    return { status: 204 };
227	  }
228	
229	  /** Saves the candidate state first; memory changes only when the save succeeded. */
230	  async function commit(candidate) {
231	    const next = Object.freeze({ nextId: candidate.nextId, bookings: Object.freeze(candidate.bookings) });
232	    await saveState(dataFile, next);
233	    state = next;
234	  }
235	
236	  async function servePage(page) {
237	    const content = await fs.promises.readFile(path.join(PUBLIC_DIR, page.file));
238	    return { status: 200, page: { type: page.type, content } };
239	  }
240	
241	  /** Routes one request (body already read) to its result, or throws HttpError. */
242	  async function route(req, body) {
243	    const target = req.url;
244	    const q = target.indexOf('?');
245	    const pathname = q === -1 ? target : target.slice(0, q);
246	    const query = q === -1 ? '' : target.slice(q + 1);
247	    const method = req.method;
248	    const only = (allowed) => {
249	      if (method !== allowed) throw new HttpError(405, MSG.method);
250	    };
251	    if (Object.hasOwn(PAGES, pathname)) {
252	      only('GET');
253	      return servePage(PAGES[pathname]);
254	    }
255	    if (pathname === '/api/rooms') {
256	      only('GET');
257	      return { status: 200, payload: { rooms: [...ROOMS] } };
258	    }
259	    if (pathname === '/api/bookings') {
260	      if (method === 'GET') return listBookings(query);
261	      if (method === 'POST') return createBooking(req, body);
262	      throw new HttpError(405, MSG.method);
263	    }
264	    if (DELETE_ROUTE.test(pathname)) {
265	      only('DELETE');
266	      return deleteBooking(pathname.slice('/api/bookings/'.length));
267	    }
268	    throw new HttpError(404, MSG.notFound);
269	  }
270	
271	  return { route };
272	}
273	
274	function writeResult(res, result) {
275	  if (result.page) {
276	    res.writeHead(200, { 'Content-Type': result.page.type, 'Content-Length': result.page.content.length });
277	    res.end(result.page.content);
278	    return;
279	  }
280	  send(res, result.status, result.payload);
281	}
282	
283	function writeFailure(res, err) {
284	  if (res.headersSent) {
285	    res.destroy();
286	    return;
287	  }
288	  if (err instanceof HttpError) sendError(res, err.status, err.message);
289	  else sendError(res, 500, MSG.internal);
290	}
291	
292	/** Serialises request handling so concurrent requests act as if handled one at a time. */
293	function createHandler(app) {
294	  let queue = Promise.resolve();
295	  return (req, res) => {
296	    // A failed write to a vanished client must not crash the server; nothing else to do.
297	    res.on('error', () => {});
298	    readBody(req).then(
299	      (body) => {
300	        queue = queue.then(() => app.route(req, body)
301	          .then((result) => writeResult(res, result), (err) => writeFailure(res, err))
302	          .catch(() => res.destroy()));
303	      },
304	      () => res.destroy(), // client aborted before sending its body: there is no one to reply to
305	    );
306	  };
307	}
308	
309	// ---------- startup ----------
310	
311	function fail(line) {
312	  process.stderr.write(`${line}\n`);
313	  process.exit(1);
314	}
315	
316	function parsePort(raw) {
317	  if (raw === undefined || raw === '') return DEFAULT_PORT;
318	  if (!/^[0-9]+$/.test(raw)) return null;
319	  const port = Number(raw);
320	  return port <= MAX_PORT ? port : null;
321	}
322	
323	function main() {
324	  const port = parsePort(process.env.PORT);
325	  if (port === null) fail(`invalid PORT ${process.env.PORT}`);
326	  const dataName = process.env.DATA_FILE || 'bookings.json';
327	  const dataFile = path.resolve(process.cwd(), dataName);
328	  const state = loadState(dataFile);
329	  if (state === null) fail(`cannot read data file ${dataName}`);
330	
331	  const server = http.createServer(createHandler(createApp(dataFile, state)));
332	  server.on('clientError', (err, socket) => {
333	    if (socket.writable && !socket.headersSent) socket.end('HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n');
334	    else socket.destroy();
335	  });
336	  server.on('error', (err) => fail(`cannot listen on port ${port}: ${err.code || 'error'}`));
337	  server.listen(port, HOST, () => {
338	    process.stdout.write(`listening on http://${HOST}:${server.address().port}\n`);
339	  });
340	}
341	
342	main();
